export const totalCoins = 942;

export function getCoinByUid(uid: string): CoinRecord | undefined {
  return coinDatabase.find(c => c.uid === uid);
}
export function getCoinsByMetal(metal: string): CoinRecord[] {
  return coinDatabase.filter(c => c.metal.toLowerCase().includes(metal.toLowerCase()));
}
export function getCoinsByYear(year: number): CoinRecord[] {
  return coinDatabase.filter(c => c.year === year);
}
